function e(string $value):string{return htmlspecialchars($value,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
function envValue(string $value):string{return '"'.str_replace(['\\','"',"\r","\n"],['\\\\','\\"','',''],$value).'"';}
function uuid():string{$d=random_bytes(16);$d[6]=chr((ord($d[6])&0x0f)|0x40);$d[8]=chr((ord($d[8])&0x3f)|0x80);return vsprintf('%s%s-%s-%s-%s-%s%s%s',str_split(bin2hex($d),4));}
function databaseDsn(string $host,int $port,string $socket='',?string $database=null):string{$base=$socket!==''?'mysql:unix_socket='.$socket:'mysql:host='.$host.';port='.$port;return $base.($database!==null?';dbname='.$database:'').';charset=utf8mb4';}
function tableNames(PDO $pdo,string $database):array{$q=$pdo->prepare('SELECT table_name FROM information_schema.tables WHERE table_schema=? AND table_type=\'BASE TABLE\'');$q->execute([$database]);return $q->fetchAll(PDO::FETCH_COLUMN);}
function defaultUrl():string{$https=isset($_SERVER['HTTPS'])&&$_SERVER['HTTPS']!=='off';$scheme=$https?'https':'http';$host=$_SERVER['HTTP_HOST']??'localhost';$path=rtrim(str_replace('\\','/',dirname($_SERVER['SCRIPT_NAME']??'/install.php')),'/');return $scheme.'://'.$host.$path.'/index.php';}

$requirements=[
 'PHP 8.2 eller nyere'=>PHP_VERSION_ID>=80200,
 'PDO MySQL'=>extension_loaded('pdo_mysql'),
 'OpenSSL'=>extension_loaded('openssl'),
 'Mbstring'=>extension_loaded('mbstring'),
 'Composer-pakker'=>is_file(__DIR__.'/vendor/autoload.php'),
 'Skrivbar systemmappe'=>is_writable(__DIR__),
