 $database=trim((string)($_POST['database']??''));$host=trim((string)($_POST['host']??'127.0.0.1'));$port=(int)($_POST['port']??3306);$username=trim((string)($_POST['username']??''));$password=(string)($_POST['password']??'');$socket=trim((string)($_POST['socket']??''));$sslCa=trim((string)($_POST['ssl_ca']??''));$databaseMode=(string)($_POST['database_mode']??'existing');
 $company=trim((string)($_POST['company']??''));$branch=trim((string)($_POST['branch']??'Hovedavdeling'));$adminName=trim((string)($_POST['admin_name']??''));$adminEmail=strtolower(trim((string)($_POST['admin_email']??'')));$adminPassword=(string)($_POST['admin_password']??'');$appUrl=rtrim(trim((string)($_POST['app_url']??defaultUrl())),'/');
 if(!preg_match('/^[A-Za-z0-9_$-]{1,64}$/',$database))$errors[]='Databasenavnet inneholder tegn MySQL-installasjonen ikke kan bruke.';
 if($host===''||strlen($host)>253||!preg_match('/^[A-Za-z0-9._:-]+$/',$host))$errors[]='Oppgi et gyldig vertsnavn eller en IP-adresse.';
 if($port<1||$port>65535)$errors[]='Porten må være mellom 1 og 65535.';
 if($username===''||strlen($username)>128)$errors[]='Oppgi databasebrukernavn.';
 if(!in_array($databaseMode,['existing','create_if_missing'],true))$errors[]='Ugyldig databasevalg.';
 if($sslCa!==''&&!is_readable($sslCa))$errors[]='SSL CA-filen kan ikke leses av PHP.';
 if($company===''||mb_strlen($company)>255)$errors[]='Oppgi bedriftsnavn.';
 if($branch===''||mb_strlen($branch)>255)$errors[]='Oppgi avdelingsnavn.';
 if($adminName===''||mb_strlen($adminName)>255)$errors[]='Oppgi administratorens navn.';
 if(!filter_var($adminEmail,FILTER_VALIDATE_EMAIL))$errors[]='Oppgi en gyldig e-postadresse.';
 if(strlen($adminPassword)<12||!preg_match('/[a-z]/',$adminPassword)||!preg_match('/[A-Z]/',$adminPassword)||!preg_match('/\d/',$adminPassword))$errors[]='Passordet må være minst 12 tegn og inneholde stor bokstav, liten bokstav og tall.';
 if(!isset($_POST['accept_legal']))$errors[]='Du må godkjenne vilkår, personvern og fakturabetaling før installasjon.';
 if(!filter_var($appUrl,FILTER_VALIDATE_URL)||!in_array(parse_url($appUrl,PHP_URL_SCHEME),['http','https'],true))$errors[]='Oppgi en gyldig HTTP- eller HTTPS-adresse.';

 if(!$errors){
  try{
   $pdoOptions=[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_EMULATE_PREPARES=>false,PDO::ATTR_TIMEOUT=>10];if($sslCa!==''&&defined('PDO::MYSQL_ATTR_SSL_CA'))$pdoOptions[PDO::MYSQL_ATTR_SSL_CA]=$sslCa;
   $server=new PDO(databaseDsn($host,$port,$socket),$username,$password,$pdoOptions);
   $exists=$server->prepare('SELECT COUNT(*) FROM information_schema.schemata WHERE schema_name=?');$exists->execute([$database]);$databaseExists=(bool)$exists->fetchColumn();
   if(!$databaseExists&&$databaseMode==='existing')throw new RuntimeException('Databasen «'.$database.'» finnes ikke, eller brukeren har ikke tilgang. Velg riktig forhåndsopprettet database.');
   if(!$databaseExists){$quoted='`'.str_replace('`','``',$database).'`';$server->exec("CREATE DATABASE {$quoted} CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci");$databaseWasCreated=true;}
   $db=new PDO(databaseDsn($host,$port,$socket,$database),$username,$password,$pdoOptions);$tables=tableNames($db,$database);
   if($tables&&!in_array('migrations',$tables,true))throw new RuntimeException('Databasen inneholder allerede tabeller som ikke tilhører en DekkPilot-installasjon. Av sikkerhetshensyn blir ingenting overskrevet.');
   if(in_array('organizations',$tables,true)&&(int)$db->query('SELECT COUNT(*) FROM organizations')->fetchColumn()>0)throw new RuntimeException('Databasen inneholder allerede en virksomhet. Bruk oppgradering/migrering i den eksisterende installasjonen, ikke install.php.');
   if(in_array('users',$tables,true)&&(int)$db->query('SELECT COUNT(*) FROM users')->fetchColumn()>0)throw new RuntimeException('Databasen inneholder allerede brukere. Installasjonen stoppes for å beskytte eksisterende data.');

   $key='base64:'.base64_encode(random_bytes(32));$assetUrl=str_ends_with($appUrl,'/index.php')?substr($appUrl,0,-10):$appUrl;$secureCookie=parse_url($appUrl,PHP_URL_SCHEME)==='https'?'true':'false';
   $env="APP_NAME=\"DekkPilot\"\nAPP_ENV=production\nAPP_KEY=".envValue($key)."\nAPP_DEBUG=false\nHASH_DRIVER=argon2id\nAPP_URL=".envValue($appUrl)."\nASSET_URL=".envValue($assetUrl)."\nAPP_LOCALE=nb\nAPP_FALLBACK_LOCALE=nb\nAPP_FAKER_LOCALE=nb_NO\n\nLOG_CHANNEL=stack\nLOG_LEVEL=warning\n\nDB_CONNECTION=mysql\nDB_HOST=".envValue($host)."\nDB_PORT={$port}\nDB_DATABASE=".envValue($database)."\nDB_USERNAME=".envValue($username)."\nDB_PASSWORD=".envValue($password)."\nDB_SOCKET=".envValue($socket)."\nDB_CHARSET=utf8mb4\nDB_COLLATION=utf8mb4_unicode_ci\nMYSQL_ATTR_SSL_CA=".envValue($sslCa)."\n\nSESSION_DRIVER=database\nSESSION_LIFETIME=120\nSESSION_ENCRYPT=true\nSESSION_SECURE_COOKIE={$secureCookie}\nSESSION_SAME_SITE=lax\nQUEUE_CONNECTION=database\nCACHE_STORE=database\nFILESYSTEM_DISK=local\n\nMAIL_MAILER=log\nMAIL_FROM_ADDRESS=".envValue($adminEmail)."\nMAIL_FROM_NAME=".envValue($company)."\n";
   $previousEnv=is_file($envPath)?file_get_contents($envPath):null;$temp=__DIR__.'/.env.installing';if(file_put_contents($temp,$env,LOCK_EX)===false||!rename($temp,$envPath))throw new RuntimeException('Kunne ikke skrive .env. Kontroller filrettighetene.');$envWritten=true;@chmod($envPath,0600);if(is_file(__DIR__.'/bootstrap/cache/config.php'))@unlink(__DIR__.'/bootstrap/cache/config.php');

   require_once __DIR__.'/vendor/autoload.php';$app=require __DIR__.'/bootstrap/app.php';$kernel=$app->make(Illuminate\Contracts\Console\Kernel::class);$kernel->bootstrap();$exit=$kernel->call('migrate',['--force'=>true,'--no-interaction'=>true]);if($exit!==0)throw new RuntimeException('Migrasjonene stoppet: '.$kernel->output());

   $db->beginTransaction();$now=date('Y-m-d H:i:s');
   $stmt=$db->prepare('INSERT INTO organizations (public_id,name,email,timezone,locale,subscription_status,billing_model,created_at,updated_at) VALUES (?,?,?,?,?,\'active\',\'invoice\',?,?)');$stmt->execute([uuid(),$company,$adminEmail,'Europe/Oslo','nb',$now,$now]);$organizationId=(int)$db->lastInsertId();
   $stmt=$db->prepare('INSERT INTO branches (public_id,organization_id,name,code,active,created_at,updated_at) VALUES (?,?,?,?,1,?,?)');$stmt->execute([uuid(),$organizationId,$branch,'HOVED',$now,$now]);$branchId=(int)$db->lastInsertId();
   $hash=password_hash($adminPassword,defined('PASSWORD_ARGON2ID')?PASSWORD_ARGON2ID:PASSWORD_BCRYPT);$isSuperAdmin=$adminEmail==='tordgladnordahl@gmail.com'?1:0;$stmt=$db->prepare('INSERT INTO users (organization_id,branch_id,name,email,password,role,active,is_super_admin,created_at,updated_at) VALUES (?,?,?,?,?,\'owner\',1,?,?,?)');$stmt->execute([$organizationId,$branchId,$adminName,$adminEmail,$hash,$isSuperAdmin,$now,$now]);$userId=(int)$db->lastInsertId();
   $location=$db->prepare('INSERT INTO storage_locations (public_id,organization_id,branch_id,code,zone,location_type,map_x,map_y,map_width,map_height,pick_order,capacity,active,created_at,updated_at) VALUES (?,?,?,?,?,?,?,?,18,14,?,20,1,?,?)');foreach(['MOTTAK','A-01','A-02','B-01','B-02']as$i=>$code)$location->execute([uuid(),$organizationId,$branchId,$code,$i===0?'Mottak':substr($code,0,1),$i===0?'receiving':'rack',($i%4)*23+3,intdiv($i,4)*20+5,$i+1,$now,$now]);
   $db->prepare('INSERT INTO service_settings (organization_id,branch_id,minutes_per_wheel,booking_buffer_minutes,quote_expiry_days,created_at,updated_at) VALUES (?,?,8,5,14,?,?)')->execute([$organizationId,$branchId,$now,$now]);
   $service=$db->prepare('INSERT INTO service_products (public_id,organization_id,code,name,category,fixed_price_cents,vat_rate,duration_minutes,active,created_at,updated_at) VALUES (?,?,?,?,?,?,25,?,1,?,?)');foreach([['HOTELL','Dekkhotell','storage',129900,20],['SKIFT','Sesongskift','tire_change',69900,40],['PLUGG','Plugging av dekk','repair',59900,30],['OMLEGG','Omlegging og balansering','workshop',129900,60],['BALANS','Balansering av hjul','workshop',79900,45],['VASK','Hjulvask','other',29900,20],['TPMS','TPMS-service','workshop',49900,30],['ETTER','Etterstramming','other',0,10]]as$s)$service->execute([uuid(),$organizationId,$s[0],$s[1],$s[2],$s[3],$s[4],$now,$now]);
   $legal=$db->prepare('INSERT INTO legal_acceptances (organization_id,user_id,document,version,ip_address,user_agent,accepted_at) VALUES (?,?,?,?,?,?,?)');foreach(['eula','privacy','pricing']as$document)$legal->execute([$organizationId,$userId,$document,'2026-08-09',$_SERVER['REMOTE_ADDR']??null,substr((string)($_SERVER['HTTP_USER_AGENT']??''),0,500),$now]);
   $db->commit();if(!is_dir(dirname($lockFile))&&!mkdir(dirname($lockFile),0750,true))throw new RuntimeException('Kunne ikke opprette installasjonslåsen.');if(file_put_contents($lockFile,json_encode(['installed_at'=>date(DATE_ATOM),'version'=>'0.2.0','database'=>$database],JSON_PRETTY_PRINT),LOCK_EX)===false)throw new RuntimeException('Kunne ikke låse installasjonen.');unset($_SESSION['install_csrf']);$success=true;
